/**
 * NocoDB Node - Version 4
 * Discriminator: resource=row, operation=upsert
 */


// Helper types for special n8n fields
type ResourceMapperField = { id?: string; displayName?: string; required?: boolean; defaultMatch?: boolean; display?: boolean; type?: string; canBeUsedToMatch?: boolean; [key: string]: unknown };
type ResourceMapperCommon = { matchingColumns?: string[]; cachedResultName?: string; [key: string]: unknown };
type ResourceMapperValue = ResourceMapperCommon & { mappingMode: string; value?: null | Record<string, unknown>; schema?: ResourceMapperField[] };

interface Credentials {
  nocoDb: CredentialReference;
  nocoDbApiToken: CredentialReference;
}

/** Create a new record, or update the current one if it already exists (upsert) */
export type NocoDbV4RowUpsertParams = {
  resource: 'row';
  operation: 'upsert';
  authentication?: 'nocoDbApiToken' | 'nocoDb' | Expression<string>;
/**
 * Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
 * @searchListMethod getWorkspaces
 * @default {"mode":"list","value":""}
 */
    workspaceId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
 * @searchListMethod getBases
 * @default {"mode":"list","value":""}
 */
    projectId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The table to operate on. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
 * @searchListMethod getTables
 * @default {"mode":"list","value":""}
 */
    table?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Whether to insert the input data this node receives in the new row
 * @default mapWithFields
 */
    dataToSend?: 'autoMapInputData' | 'mapWithFields' | Expression<string>;
/**
 * The value of the ID field. Keep empty for create (insert).
 */
    id?: string | Expression<string>;
/**
 * List of input properties to avoid sending, separated by commas. Leave empty to send all properties.
 * @displayOptions.show { dataToSend: ["autoMapInputData"] }
 */
    inputsToIgnore?: string | Expression<string>;
/**
 * Fields to Send
 * @displayOptions.show { dataToSend: ["mapWithFields"] }
 * @default {"mappingMode":"defineBelow","value":null}
 */
    fieldsMapper?: ResourceMapperValue;
};

export type NocoDbV4RowUpsertNode = {
  type: 'n8n-nodes-base.nocoDb';
  version: 4;
  config: NodeConfig<NocoDbV4RowUpsertParams> & { credentials?: Credentials };
};